package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
final class ConversationCollections {
 static JSONArray group(JSONArray history)throws Exception{LinkedHashMap<String,JSONObject> groups=new LinkedHashMap<>();for(int i=0;i<history.length();i++){JSONObject raw=history.getJSONObject(i),row=new JSONObject().put("kind",raw.optString("kind")).put("time",raw.optLong("time")).put("message",raw.optString("message"));String id=raw.optString("requestId");if(TrackedWebRequest.validId(id))row.put("requestId",id);String key=TrackedWebRequest.validId(id)?id:RecorderPhotoStore.hash(row.toString().getBytes("UTF-8"));if(raw.optBoolean("legacy"))row.put("legacy",true);JSONObject card=groups.get(key);if(card==null){card=new JSONObject().put("key",key).put("title",row.optString("message").substring(0,Math.min(80,row.optString("message").length()))).put("rows",new JSONArray());groups.put(key,card);}card.getJSONArray("rows").put(row);}JSONArray result=new JSONArray();for(JSONObject card:groups.values()){String revision=RecorderPhotoStore.hash(card.getJSONArray("rows").toString().getBytes("UTF-8"));result.put(card.put("revision",revision));}return result;}
 static synchronized JSONArray favorites(Context c)throws Exception{JSONArray rows=ReviewStore.read(c,"conversation-favorites").optJSONArray("items");return rows==null?new JSONArray():rows;}
 static JSONObject library(MainActivity owner)throws Exception{return new JSONObject().put("items",group(owner.webHistory())).put("favorites",favorites(owner));}
 static synchronized JSONObject favorite(Context c,JSONArray history,JSONObject input)throws Exception{String key=input.getString("key"),action=input.getString("action");if(!TrackedWebRequest.validId(key)||!action.matches("save|remove"))throw new IOException("操作が不正です");JSONArray all=favorites(c),next=new JSONArray();JSONObject old=null;for(int i=0;i<all.length();i++){JSONObject row=all.getJSONObject(i);if(key.equals(row.optString("key")))old=row;else next.put(row);}if(action.equals("remove")){if(old==null)return new JSONObject().put("removed",true).put("duplicate",true);if(!old.getString("revision").equals(input.getString("revision")))throw new IOException("保存内容が変わりました");ReviewStore.write(c,"conversation-favorites",new JSONObject().put("items",next));return new JSONObject().put("removed",true);}
 JSONArray groups=group(history);JSONObject source=null;for(int i=0;i<groups.length();i++)if(key.equals(groups.getJSONObject(i).getString("key")))source=groups.getJSONObject(i);if(source==null||!source.getString("revision").equals(input.getString("revision")))throw new IOException("元の会話が更新・削除されました。開き直してください");if(old!=null){if(!old.getString("revision").equals(source.getString("revision")))throw new IOException("別内容を保存済みです。必要ならお気に入りから削除して保存し直してください");return new JSONObject().put("saved",true).put("duplicate",true);}if(next.length()>=50||source.toString().length()>50000)throw new IOException("お気に入りは50件・1件5万文字以内です");next.put(new JSONObject(source.toString()).put("savedAt",System.currentTimeMillis()));ReviewStore.write(c,"conversation-favorites",new JSONObject().put("items",next));return new JSONObject().put("saved",true);}
 static String export(Context c,JSONArray history,JSONObject input)throws Exception{JSONArray selected=input.getJSONArray("items"),source=input.optBoolean("favorites")?favorites(c):group(history);if(selected.length()==0||selected.length()>20)throw new IOException("1〜20件を選んでください");HashSet<String> seen=new HashSet<>();StringBuilder text=new StringBuilder("電脳秘書ロキ・選択した会話\n\n");for(int i=0;i<selected.length();i++){JSONObject choice=selected.getJSONObject(i);String key=choice.getString("key");if(!seen.add(key))throw new IOException("同じ会話が重複しています");JSONObject card=null;for(int j=0;j<source.length();j++)if(key.equals(source.getJSONObject(j).getString("key")))card=source.getJSONObject(j);if(card==null||!card.getString("revision").equals(choice.getString("revision")))throw new IOException("選択内容が変わりました。開き直してください");JSONArray rows=card.getJSONArray("rows");for(int j=0;j<rows.length();j++){JSONObject row=rows.getJSONObject(j);text.append(row.optString("kind")).append(" / ").append(new java.util.Date(row.optLong("time"))).append("\n").append(row.optString("message")).append("\n\n");if(text.length()>200000)throw new IOException("書き出しが大きすぎます。選択を減らしてください");}text.append("---\n\n");}return text.toString();}
 private ConversationCollections(){}
}
